package dev.campus.atlas;

import android.app.Application;
import android.content.SharedPreferences;
import android.location.Location;
import dev.campus.atlas.core.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import org.robolectric.shadows.ShadowSystemClock;
import java.time.Duration;
import java.util.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,application=Application.class)
public class SystemLocationOutputTest {
    static class FakeBackend implements SystemLocationOutput.Backend {
        final Map<String,Location> locations=new HashMap<>();final List<String> removed=new ArrayList<>(),writeOrder=new ArrayList<>();String reason="";boolean failNetwork,failRemove,mock=true;int writes,prepares,transientFailures,attempts;boolean denyWrite;
        public String unavailableReason(){return reason;}
        public void prepare(String provider){prepares++;}
        public void publish(String provider,Location location){attempts++;writeOrder.add(provider);if(denyWrite)throw new SecurityException("revoked");if(transientFailures>0){transientFailures--;throw new IllegalStateException("temporarily unavailable");}if(failNetwork&&"network".equals(provider))throw new IllegalStateException("network failed");writes++;locations.put(provider,new Location(location));}
        public SystemLocationOutput.Sample read(String provider){Location l=locations.get(provider);return l==null?null:new SystemLocationOutput.Sample(new Point(l.getLatitude(),l.getLongitude()),l.getElapsedRealtimeNanos(),mock);}
        public void remove(String provider){if(failRemove)throw new SecurityException("revoked");removed.add(provider);locations.remove(provider);}
    }
    Application app;SharedPreferences journal;FakeBackend backend;SystemLocationOutput output;
    @Before public void setup(){app=RuntimeEnvironment.getApplication();journal=app.getSharedPreferences("playback_recovery",0);journal.edit().clear().commit();app.getSharedPreferences("atlas",0).edit().clear().commit();backend=new FakeBackend();output=new SystemLocationOutput(app,backend);}
    @Test public void missingAuthorizationDoesNotWriteProvidersOrRecoveryRecord(){backend.reason="未授权";try{output.publish(new Point(30,120));fail();}catch(IllegalStateException expected){}assertEquals(0,backend.writes);assertFalse(journal.contains("pending_target"));}
    @Test public void publishesCompleteLocationsToBothProvidersAndVerifiesReadback(){output.publish(new Point(30,120));assertEquals(2,backend.writes);for(Location l:backend.locations.values()){assertEquals(30,l.getLatitude(),0);assertTrue(l.hasAccuracy());assertTrue(l.getTime()>0);assertTrue(l.hasSpeed());}assertTrue(output.verified());assertEquals(SystemLocationOutput.TARGET,journal.getString("pending_target",""));}
    @Test public void ordinaryOrStaleLocationIsNotReportedAsMockReadback(){backend.mock=false;output.publish(new Point(30,120));assertFalse(output.verified());assertTrue(output.status().contains("等待"));}
    @Test public void previousConfirmationExpiresWhenTheWriterStops(){output.publish(new Point(30,120));assertTrue(output.verified());ShadowSystemClock.advanceBy(Duration.ofSeconds(6));assertFalse(output.verified());assertTrue(output.status().contains("等待"));}
    @Test public void switchedRealLocationInvalidatesPreviousConfirmation(){output.publish(new Point(30,120));assertTrue(output.verified());backend.mock=false;assertFalse(output.verified());assertTrue(output.diagnostics().contains("非模拟数据"));}
    @Test public void missingOrMismatchingProviderInvalidatesPreviousConfirmation(){output.publish(new Point(30,120));assertTrue(output.verified());backend.locations.remove("gps");assertFalse(output.verified());Location other=new Location("gps");other.setLatitude(31);other.setLongitude(121);other.setElapsedRealtimeNanos(android.os.SystemClock.elapsedRealtimeNanos());backend.locations.put("gps",other);assertFalse(output.verified());}
    @Test public void oldTargetCannotConfirmTheNextTarget(){output.publish(new Point(30,120));assertTrue(output.verified());backend.mock=false;output.publish(new Point(31,121));assertFalse(output.verified());assertTrue(output.status().contains("等待"));}
    @Test public void stopRemovesBothTestProvidersAndClearsJournal(){output.publish(new Point(30,120));output.reset();assertTrue(backend.locations.isEmpty());assertEquals(2,backend.removed.size());assertFalse(journal.contains("pending_target"));assertFalse(output.verified());output.reset();assertEquals(2,backend.removed.size());}
    @Test public void partialWriteFailureRollsBackGpsAndNetwork(){backend.failNetwork=true;try{output.publish(new Point(30,120));fail();}catch(IllegalStateException expected){}assertTrue(backend.locations.isEmpty());assertFalse(journal.contains("pending_target"));}
    @Test public void failedCleanupPreservesRecoveryRecord(){output.publish(new Point(30,120));backend.failRemove=true;try{output.reset();fail();}catch(IllegalStateException expected){}assertEquals(SystemLocationOutput.TARGET,journal.getString("pending_target",""));backend.failRemove=false;output.reset();assertFalse(journal.contains("pending_target"));}
    @Test public void recoveryUsesSystemOutputWithoutPublishingNewCoordinates(){journal.edit().putString("pending_target",SystemLocationOutput.TARGET).commit();PlaybackRuntime recovered=new PlaybackRuntime(app,output);assertEquals(SystemLocationOutput.DESCRIPTION,recovered.output.description());assertEquals(RoutePlayer.State.ERROR,recovered.player.snapshot().state);assertEquals(0,backend.writes);recovered.player.stop(true);assertFalse(journal.contains("pending_target"));}
    @Test public void singleTransientWriteRetriesWithoutRecreatingProviders(){output.publish(new Point(30,120));backend.transientFailures=1;output.publish(new Point(30,120));assertEquals(4,backend.writes);assertEquals(2,backend.prepares);assertTrue(backend.removed.isEmpty());assertTrue(output.verified());}
    @Test public void permissionFailureIsNotRetriedAndRollsBack(){backend.denyWrite=true;try{output.publish(new Point(30,120));fail();}catch(IllegalStateException expected){}assertEquals(1,backend.attempts);assertTrue(backend.locations.isEmpty());assertFalse(journal.contains("pending_target"));}
    @Test public void repeatedInitialFailureTriesBothProvidersThenRollsBack(){backend.transientFailures=10;try{output.publish(new Point(30,120));fail();}catch(IllegalStateException expected){}assertEquals(4,backend.attempts);assertEquals(Arrays.asList("network","network","gps","gps"),backend.writeOrder);assertTrue(backend.locations.isEmpty());assertFalse(journal.contains("pending_target"));}
    @Test public void motionHasActualBearingAndResetsOnTeleport(){output.publish(new Point(0,0));ShadowSystemClock.advanceBy(Duration.ofSeconds(1));output.publish(new Point(0,0.0001));Location l=backend.locations.get("gps");assertEquals(90,l.getBearing(),0.01);assertTrue(l.getSpeed()>10);ShadowSystemClock.advanceBy(Duration.ofMillis(100));output.publish(new Point(0,0.0001));assertEquals(90,backend.locations.get("gps").getBearing(),0.01);output.beginSegment();output.publish(new Point(20,120));assertEquals(0,backend.locations.get("gps").getSpeed(),0);assertEquals(0,backend.locations.get("gps").getBearing(),0);}
    @Test public void gpsAndNetworkHaveReferenceSampleFieldsAndWriteOrder(){output.publish(new Point(30,120));assertEquals(Arrays.asList("network","gps"),backend.writeOrder);Location gps=backend.locations.get("gps"),network=backend.locations.get("network");assertEquals(1,gps.getAccuracy(),0);assertEquals(2,network.getAccuracy(),0);assertEquals(55,gps.getAltitude(),0);assertTrue(gps.hasAltitude());assertEquals(7,gps.getExtras().getInt("satellites"));assertNull(network.getExtras());assertEquals(gps.getLatitude(),network.getLatitude(),0);assertEquals(gps.getElapsedRealtimeNanos(),network.getElapsedRealtimeNanos());}
    @Test public void establishedNetworkFailureDoesNotInterruptGpsOrRemoveProviders(){output.publish(new Point(30,120));backend.failNetwork=true;ShadowSystemClock.advanceBy(Duration.ofMillis(100));long previous=backend.locations.get("gps").getElapsedRealtimeNanos();output.publish(new Point(30,120));assertTrue(backend.locations.get("gps").getElapsedRealtimeNanos()>previous);assertTrue(backend.removed.isEmpty());assertFalse(output.verified());assertTrue(output.status().contains("重试"));backend.failNetwork=false;output.publish(new Point(30,120));assertTrue(output.verified());assertEquals(2,backend.prepares);assertTrue(backend.removed.isEmpty());}
    @Test public void persistentEstablishedFailureRestoresAfterBoundedGrace(){output.publish(new Point(30,120));backend.failNetwork=true;output.publish(new Point(30,120));output.publish(new Point(30,120));assertTrue(backend.removed.isEmpty());try{output.publish(new Point(30,120));fail();}catch(IllegalStateException expected){}assertTrue(backend.locations.isEmpty());assertFalse(journal.contains("pending_target"));}
    @Test public void fusedReadbackIsDiagnosticAndCannotConfirmDualProviderSuccess(){output.publish(new Point(30,120));Location fused=new Location("fused");fused.setLatitude(31);fused.setLongitude(121);fused.setElapsedRealtimeNanos(android.os.SystemClock.elapsedRealtimeNanos());backend.locations.put("fused",fused);assertTrue(output.diagnostics().contains("fused:"));backend.locations.remove("gps");assertFalse(output.verified());}
    @Test public void configuredProviderPropertiesMatchReference(){android.location.provider.ProviderProperties network=SystemLocationOutput.providerProperties("network"),gps=SystemLocationOutput.providerProperties("gps");assertEquals(2,network.getAccuracy());assertEquals(1,network.getPowerUsage());assertTrue(network.hasMonetaryCost());assertTrue(network.hasNetworkRequirement());assertTrue(network.hasCellRequirement());assertEquals(1,gps.getAccuracy());assertEquals(3,gps.getPowerUsage());assertFalse(gps.hasMonetaryCost());assertTrue(gps.hasSatelliteRequirement());}
}